import click
from click.shell_completion import CompletionItem

class Foo(click.ParamType):
    def convert(self, value, param, ctx):
        return value

    def shell_complete(self, ctx, param, incomplete):
        return [
            CompletionItem(value=value, help="adsf") for value in 
            ["baz:quux", "spam:eggs"]
        ]

@click.command()
@click.argument("foo", type=Foo())
def main(foo):
    print(foo)


def test_shell_completion():
    cli = click.Command('foo', params=[click.Argument(['foo'], type=Foo())])
    completions = cli.get_completion('', 'foo', '')
    completion_values = [c.value for c in completions]
    assert 'baz:quux' in completion_values
    assert 'spam:eggs' in completion_values
    assert 'baz' in completion_values
    assert 'spam' in completion_values
    assert 'quux' not in completion_values
    assert 'eggs' not in completion_values

